package com.abhishek.ecommerce.payment;
import com.abhishek.ecommerce.common.DomainEvent;import org.springframework.context.annotation.*;import org.springframework.kafka.support.serializer.JsonSerializer;import org.springframework.kafka.core.*;import java.util.*;
@Configuration public class KafkaConfig{@Bean ProducerFactory<String,DomainEvent>producerFactory(){Map<String,Object>p=new HashMap<>();p.put("bootstrap.servers","localhost:9092");p.put("key.serializer","org.apache.kafka.common.serialization.StringSerializer");p.put("value.serializer",JsonSerializer.class);return new DefaultKafkaProducerFactory<>(p);}@Bean KafkaTemplate<String,DomainEvent>kafkaTemplate(){return new KafkaTemplate<>(producerFactory());}}